using System.Reflection;
using Core.Application.Handlers.Lobby;
using Core.Application.Notifications.Network;
using Core.Network.FusionAdapter.Runner;
using Core.Presentation.MVVM.Models.Lobby;
using Cysharp.Threading.Tasks;
using Fusion;

sealed class Logger : Core.Abstractions.Services.ILogger { public void Error(string f, params object[] a) {} public void Info(string f, params object[] a) {} }
sealed class Mediator : Core.Mediator.Abstractions.IMediator {
 public readonly LobbyModel Model = new();
 public readonly List<NetworkSessionListUpdatedNotification> Pending = new();
 public bool Delay;
 public Action OnPublish;
 public UniTask Publish(object n) { var value=(NetworkSessionListUpdatedNotification)n; if(Delay) Pending.Add(value); else Deliver(value); OnPublish?.Invoke(); return UniTask.CompletedTask; }
 public void Deliver(NetworkSessionListUpdatedNotification value) => new SessionListSyncHandler(Model).Handle(value, default);
}
class Program {
 static int failures;
 static void Assert(bool condition, string message) { if(!condition) throw new Exception(message); }
 static void Callback(FusionLobbyController c,string name,params object[] args) => typeof(FusionLobbyController).GetMethod(name, BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,args);
 static void Update(FusionLobbyController c,NetworkRunner r,string name) => Callback(c,"OnSessionListUpdated",r,new List<SessionInfo>{new(){Name=name}});
 static async Task<(FusionLobbyController,NetworkRunner)> Join(Mediator m) { NetworkRunner.Join=(r,t)=>{r.LobbyInfo.IsValid=true; return Task.FromResult(new StartGameResult{Ok=true});}; var c=new FusionLobbyController(m,new Logger()); await c.JoinAsync(); return(c,NetworkRunner.All[^1]); }
 static async Task Run(string name,Func<Task> test) { try { await test(); Console.WriteLine("PASS "+name); } catch(Exception e) { failures++; Console.WriteLine("FAIL "+name+": "+e.Message); } }
 static async Task Main() {
  await Run("leave clears model",async()=>{var m=new Mediator(); var(c,r)=await Join(m); Update(c,r,"old"); await c.LeaveAsync(); Assert(m.Model.Sessions.Count==0,"model still contains old room");});
  await Run("old callback cannot overwrite new list",async()=>{var m=new Mediator(); var(c,old)=await Join(m); await c.LeaveAsync(); NetworkRunner.Join=(r,t)=>{r.LobbyInfo.IsValid=true; return Task.FromResult(new StartGameResult{Ok=true});}; await c.JoinAsync(); var current=NetworkRunner.All[^1]; Update(c,current,"new"); Update(c,old,"old"); Assert(m.Model.Sessions[0].RoomCode=="new","old callback overwrote model");});
  await Run("current shutdown clears model",async()=>{var m=new Mediator(); var(c,r)=await Join(m); Update(c,r,"old"); Callback(c,"OnShutdown",r,ShutdownReason.None); Assert(m.Model.Sessions.Count==0,"model still contains old room");});
  await Run("old shutdown cannot clear new controller list",async()=>{var m=new Mediator(); var(c,old)=await Join(m); await c.LeaveAsync(); await c.JoinAsync(); Update(c,NetworkRunner.All[^1],"new"); Callback(c,"OnShutdown",old,ShutdownReason.None); Assert(c.Sessions.Count==1 && m.Model.Sessions.Count==1,"old shutdown cleared current sessions");});
  await Run("out-of-order delivery cannot overwrite new list",async()=>{var m=new Mediator(); var(c,old)=await Join(m); m.Delay=true; Update(c,old,"old"); await c.LeaveAsync(); await c.JoinAsync(); Update(c,NetworkRunner.All[^1],"new"); m.Deliver(m.Pending[^1]); m.Deliver(m.Pending[0]); Assert(m.Model.Sessions[0].RoomCode=="new","delayed old notification overwrote model");});
  await Run("leave invokes current runner shutdown",async()=>{var m=new Mediator(); var(c,r)=await Join(m); await c.LeaveAsync(); Assert(r.ShutdownCalls==1,"current runner shutdown was not called exactly once");});
  await Run("same-session out-of-order delivery cannot overwrite new list",async()=>{var m=new Mediator(); var(c,r)=await Join(m); m.Delay=true; Update(c,r,"old"); Update(c,r,"new"); m.Deliver(m.Pending[1]); m.Deliver(m.Pending[0]); Assert(m.Model.Sessions[0].RoomCode=="new","delayed same-session notification overwrote model");});
  await Run("legacy unversioned notification applies",()=>{var m=new Mediator(); m.Deliver(new NetworkSessionListUpdatedNotification(new[]{new Core.Network.Abstractions.Types.NetworkSessionInfo("legacy", "region", 1, 4, true, true)})); Assert(m.Model.Sessions.Count==1 && m.Model.Sessions[0].RoomCode=="legacy","legacy notification not applied"); return Task.CompletedTask;});
  await Run("null runner callbacks ignored",async()=>{var m=new Mediator(); var(c,r)=await Join(m); await c.LeaveAsync(); Update(c,null,"ghost"); Callback(c,"OnShutdown",null,ShutdownReason.None); Assert(c.Sessions.Count==0 && m.Model.Sessions.Count==0,"null callback accepted");});
  await Run("reentrant join during shutdown cannot replace runner",async()=>{var m=new Mediator(); var(c,r)=await Join(m); Update(c,r,"old"); Task reentrant=null; m.OnPublish=()=>{m.OnPublish=null; reentrant=c.JoinAsync().AsTask();}; NetworkRunner.OnShutdown=runner=>{Callback(c,"OnShutdown",runner,ShutdownReason.None); return Task.CompletedTask;}; try {await c.LeaveAsync(); Assert(reentrant!=null,"shutdown did not publish empty update"); try {await reentrant; throw new Exception("reentrant join accepted");} catch(InvalidOperationException) {} Assert(r.ShutdownCalls==1 && c.Sessions.Count==0,"shutdown lost runner");} finally {NetworkRunner.OnShutdown=null;}});
  await Run("late updates during leave and old shutdown ignored",async()=>{var m=new Mediator(); var(c,r)=await Join(m); Update(c,r,"old"); var gate=new TaskCompletionSource(); NetworkRunner.OnShutdown=_=>gate.Task; try {var leave=c.LeaveAsync(); Update(c,r,"late"); Assert(c.Sessions.Count==0 && m.Model.Sessions.Count==0,"late update accepted during leave"); gate.SetResult(); await leave; await c.JoinAsync(); var next=NetworkRunner.All[^1]; Update(c,next,"new"); Callback(c,"OnShutdown",r,ShutdownReason.None); Assert(c.Sessions.Count==1 && m.Model.Sessions[0].RoomCode=="new","late shutdown affected new runner");} finally {NetworkRunner.OnShutdown=null;}});
  await Run("reentrant join during unsolicited shutdown rejected",async()=>{var m=new Mediator(); var(c,r)=await Join(m); Update(c,r,"old"); r.LobbyInfo.IsValid=false; r.IsShutdown=true; Task join=null; m.OnPublish=()=>{m.OnPublish=null; join=c.JoinAsync().AsTask();}; Callback(c,"OnShutdown",r,ShutdownReason.None); Assert(join!=null,"missing shutdown notification"); try {await join; throw new Exception("reentrant join accepted during callback");} catch(InvalidOperationException) {}});
  await Run("concurrent join and leave rejected until shutdown completes",async()=>{var m=new Mediator(); var(c,r)=await Join(m); var gate=new TaskCompletionSource(); NetworkRunner.OnShutdown=_=>gate.Task; try {var leave=c.LeaveAsync(); try {await c.JoinAsync(); throw new Exception("join accepted");} catch(InvalidOperationException) {} try {await c.LeaveAsync(); throw new Exception("second leave accepted");} catch(InvalidOperationException) {} Assert(r.ShutdownCalls==1,"multiple shutdowns"); gate.SetResult(); await leave; await c.JoinAsync(); Assert(!ReferenceEquals(r,NetworkRunner.All[^1]),"new runner not created");} finally {NetworkRunner.OnShutdown=null;}});
  await Run("leave cancellation waits for shutdown before releasing runner",async()=>{var m=new Mediator(); var(c,r)=await Join(m); var gate=new TaskCompletionSource(); using var cancel=new CancellationTokenSource(); NetworkRunner.OnShutdown=_=>gate.Task; try {var leave=c.LeaveAsync(cancel.Token); cancel.Cancel(); try {await c.JoinAsync(); throw new Exception("join accepted before shutdown");} catch(InvalidOperationException) {} gate.SetResult(); try {await leave; throw new Exception("cancellation ignored");} catch(OperationCanceledException) {} await c.JoinAsync(); Assert(!ReferenceEquals(r,NetworkRunner.All[^1]),"runner not replaced after shutdown");} finally {NetworkRunner.OnShutdown=null;}});
  await Run("shutdown failure propagated and operation can retry",async()=>{var m=new Mediator(); var(c,r)=await Join(m); NetworkRunner.OnShutdown=_=>Task.FromException(new Exception("shutdown error")); try {try {await c.LeaveAsync(); throw new Exception("error swallowed");} catch(Exception e) when(e.Message=="shutdown error") {} NetworkRunner.OnShutdown=null; await c.LeaveAsync(); Assert(r.ShutdownCalls==2,"retry did not use same runner");} finally {NetworkRunner.OnShutdown=null;}});
  await Run("unsolicited shutdown requires awaited leave before rejoin",async()=>{var m=new Mediator(); var(c,r)=await Join(m); r.IsShutdown=true; r.LobbyInfo.IsValid=false; Callback(c,"OnShutdown",r,ShutdownReason.None); try {await c.JoinAsync(); throw new Exception("join accepted without shutdown completion");} catch(InvalidOperationException) {} await c.LeaveAsync(); await c.JoinAsync(); Assert(!ReferenceEquals(r,NetworkRunner.All[^1]),"runner not replaced");});
  await Run("failed shutdown blocks join until successful retry",async()=>{var m=new Mediator(); var(c,r)=await Join(m); NetworkRunner.OnShutdown=_=>Task.FromException(new Exception("shutdown error")); try {try {await c.LeaveAsync();} catch(Exception e) when(e.Message=="shutdown error") {} try {await c.JoinAsync(); throw new Exception("join accepted after failed shutdown");} catch(InvalidOperationException) {} NetworkRunner.OnShutdown=null; await c.LeaveAsync(); await c.JoinAsync();} finally {NetworkRunner.OnShutdown=null;}});
  Console.WriteLine($"Failures: {failures}"); Environment.ExitCode=failures==0?0:1;
 }
}
